class SecretsStore(dict):
    def _get_secret_name(self, key):
        # A secret can be retrieved using the name, the full ARN, or a
        # partial ARN (the ARN without the random suffix)
        if key.startswith("arn:aws:secretsmanager:"):
            # A full ARN matches the ARN of a stored secret exactly
            for name, secret in dict.items(self):
                if secret.arn == key:
                    return name
            # A partial ARN ends with the secret name
            return key.split(":")[-1]
        return key

    def __setitem__(self, key, value):
        new_key = self._get_secret_name(key)
        super().__setitem__(new_key, value)

    def __getitem__(self, key):
        new_key = self._get_secret_name(key)
        return super().__getitem__(new_key)

    def __contains__(self, key):
        new_key = self._get_secret_name(key)
        return dict.__contains__(self, new_key)

    def get(self, key, *args, **kwargs):
        new_key = self._get_secret_name(key)
        return super().get(new_key, *args, **kwargs)

    def pop(self, key, *args, **kwargs):
